def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    # The colored information lies on the zero separator rows and columns.
    # Collapse each pair of adjacent separator bands into one output cell.
    rows = [r for r in range(h) if all(x == 0 for x in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == 0 for r in range(h))]
    out = [[bg for _ in range(max(1, (len(cols)-1)//2))] for _ in range(max(1, (len(rows)-1)//2))]
    for i in range(len(out)):
        for j in range(len(out[0])):
            vals = []
            for r in rows[1+2*i:1+2*i+2]:
                for c in cols[2*j:2*j+2]:
                    if grid[r][c] not in (0, bg):
                        vals.append(grid[r][c])
            if vals:
                out[i][j] = vals[0]
    return out
