def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])

    # The dominant nonzero color fills the repeated tiles and the output.
    freq = Counter(v for row in grid for v in row if v != 0)
    fill = freq.most_common(1)[0][0]

    # Separator rows/columns are mostly zero. Colored pixels on them form
    # the encoded output lattice.
    sep_rows = [r for r in range(h) if sum(v == 0 for v in grid[r]) > w // 2]
    sep_cols = [c for c in range(w) if sum(grid[r][c] == 0 for r in range(h)) > h // 2]

    active_rows = [
        r for r in sep_rows
        if any(grid[r][c] not in (0, fill) for c in range(w))
    ]
    marks = [(r, c, grid[r][c]) for r in active_rows for c in range(w)
             if grid[r][c] not in (0, fill)]

    if not marks:
        return [[fill]]

    # Marked columns fall on a regular lattice; include unmarked lattice
    # positions between the outermost marked columns.
    marked_cols = sorted(set(c for _, c, _ in marks))
    diffs = [b - a for a, b in zip(marked_cols, marked_cols[1:])]
    step = 0
    for d in diffs:
        if d > 0:
            if not step:
                step = d
            else:
                import math
                step = math.gcd(step, d)
    if not step:
        step = 1

    c0, c1 = marked_cols[0], marked_cols[-1]
    cols = list(range(c0, c1 + 1, step))
    out = [[fill for _ in cols] for _ in active_rows]
    row_index = {r: i for i, r in enumerate(active_rows)}
    col_index = {c: j for j, c in enumerate(cols)}
    for r, c, v in marks:
        if c in col_index:
            out[row_index[r]][col_index[c]] = v
    return out
